package bergdb.core;

import bergdb.dag.KeyNode;
import bergdb.dag.TopNode;

/**
 * Runs TransSeq.take (bergdb b8ac8a1) on cases generated by SplitMix64 from the case number,
 * for the Lean model's javaTake (bergdb 007-08), and prints the number of transactions taken
 * in each case; lean/SIS/BoundExample.lean makes the same cases as streams of the model, with
 * the same generator (takeCase), and compares. With the argument "bits", it prints the bits of
 * TransSeq.dither and of the share's expression for the checks there.
 *
 * A case: records R(0), ..., R(s), s = a - 1, then the TransSeq, T(s+1), ..., T(s+n); each
 * record has own bytes 48 + below(400) and a size of its own bytes and below(3000); each
 * transaction of the TransSeq has below(30) got-dirty nodes; the setting is 10 + below(SDMAX),
 * SDMAX = 16000 (-Dsdmax); the record's own bytes 48 + below(400). The record limit is not
 * used (maxBytes = Long.MAX_VALUE), as in the model.
 *
 * Run from this directory, with a bergdb.jar of b8ac8a1 or later, or with TransSeq.java
 * compiled first, as on 2026-10-28 against the main tree's jar of 2026-10-27:
 *
 *     javac -cp ../../../java/build/bergdb.jar -d /tmp/tc ../../../java/src/bergdb/core/TransSeq.java TakeCheck.java
 *     java -ea -cp /tmp/tc:../../../java/build/bergdb.jar bergdb.core.TakeCheck 300
 */
public class TakeCheck {
    static int SDMAX = Integer.getInteger("sdmax", 16000);
    static long state;

    static long next() {
        long z = (state += 0x9E3779B97F4A7C15L);
        z = (z ^ (z >>> 30)) * 0xBF58476D1CE4E5B9L;
        z = (z ^ (z >>> 27)) * 0x94D049BB133111EBL;
        return z ^ (z >>> 31);
    }

    static int below(int k) {
        return (int) Long.remainderUnsigned(next(), k);
    }

    static final TransSeq.TransNodesForMe IGNORE = new TransSeq.TransNodesForMe() {
        public void addTopNode(TopNode node) {}
        public void addKeyNode(KeyNode node) {}
    };

    /** The share's expression of TransSeq.take, with its types. */
    static double share(long dirtyCount, long recordOwnBytes, long ownBytes, long sectionLength,
            int startupDistance) {
        return (double) dirtyCount * recordOwnBytes / ownBytes * sectionLength / startupDistance;
    }

    public static void main(String[] args) {
        if (args[0].equals("bits")) {
            // TransSeq.dither and the share's expression, as Double.doubleToLongBits.
            long[] ps = {0, 1, 1200, 1300, 123456789L, 50000000000L, 9007199254740993L};
            StringBuilder b = new StringBuilder();
            for (long p : ps) {
                b.append(b.length() == 0 ? "" : ", ").append(Double.doubleToLongBits(TransSeq.dither(p)));
            }
            System.out.println("dither: [" + b + "]");
            System.out.println("share 100 100 1000 2000 800: "
                    + Double.doubleToLongBits(share(100, 100, 1000, 2000, 800)));
            System.out.println("share 7 333 1001 12345 997: "
                    + Double.doubleToLongBits(share(7, 333, 1001, 12345, 997)));
            System.out.println("share 123457 48 9999991 50000017 50000000: "
                    + Double.doubleToLongBits(share(123457, 48, 9999991, 50000017, 50000000)));
            return;
        }
        int cases = Integer.parseInt(args[0]);
        StringBuilder sb = new StringBuilder();
        int middle = 0, nonEmpty = 0, atSpan = 0, byDeadline = 0, byShareOnly = 0, moreThanDeadline = 0;
        for (int c = 0; c < cases; c++) {
            state = c;
            int a = 1 + below(4);
            int n = below(13);
            int sd = 10 + below(SDMAX);
            long o = 48 + below(400);
            below(5);                       // got-dirty nodes of T(i), for the model's D only
            TransSeq s = new TransSeq();
            long[] tposes = new long[n];
            long p = 0;
            long currentSp = 0;
            for (int j = 0; j < a + n; j++) {
                long own = 48 + below(400);
                long size = own + below(3000);
                if (j == a - 1) {
                    currentSp = p;
                }
                if (j >= a) {
                    int count = below(30);
                    TransSeq.TransInfo info = new TransSeq.TransInfo();
                    info.tpos = p;
                    tposes[j - a] = p;
                    info.lastPos = p + size - 1;
                    info.ownBytes = own;
                    for (int k = 0; k < count; k++) {
                        KeyNode node = new KeyNode();
                        node.setDirty(true);
                        info.gotDirtyNodes.add(node);
                    }
                    s.add(info);
                }
                p += size;
            }
            long streamLength = p;
            int before = s.getSize();
            long hardSp = streamLength - Math.max(2L * sd, s.span());
            int due = 0;                    // the transactions the deadline takes
            for (long t : tposes) {
                if (t <= hardSp) due++;
            }
            if (before > 0) nonEmpty++;
            if (before > 0 && s.span() > 2L * sd) atSpan++;
            s.take(currentSp, streamLength, sd, o, IGNORE, Long.MAX_VALUE);
            int taken = before - s.getSize();
            if (due > 0) byDeadline++;
            if (due == 0 && taken > 0) byShareOnly++;
            if (taken > due) moreThanDeadline++;
            if (taken < before && taken > due) middle++;
            sb.append(taken);
            sb.append(c + 1 < cases ? ", " : "");
        }
        System.out.println("[" + sb + "]");
        System.err.println("cases " + cases + ", TransSeq not empty " + nonEmpty
                + ", span > 2 sd " + atSpan + ", the deadline takes some " + byDeadline
                + ", the share alone takes some " + byShareOnly
                + ", the share takes more than the deadline " + moreThanDeadline
                + ", the share stops before the end " + middle);
    }
}
